mapper.select:
SELECT *
FROM  stock_info
WHERE 1=1

	AND type = #{type}


	AND stock_status = #{status}

SELECT a.code, a.code_name codeName, a.ipo_date ipoDate, a.out_date out_date, a.type, a.stock_status stockStatus FROM stock_info a WHERE 1 = 1
AND a.type = #{type}
AND (code like '%${key}%' OR code_name like '%${key}%')

SELECT *
FROM  stock_info a
WHERE
stock_status=1

	AND type = #{type}

AND NOT EXISTS (SELECT id FROM stock_profit b WHERE b.code=a.code

	AND
	b.year = #{year}


	AND
	b.quarter = #{quarter}

)
order by a.code

SELECT
*
FROM
stock_info
WHERE CODE NOT IN ( SELECT distinct(CODE) FROM stock_kline
WHERE 1=1

	AND DATE_FORMAT( date, '%Y-%m-%d' ) = #{date}

)

	AND type = #{type}


	AND stock_status = #{status}

order by type

SELECT *
FROM  stock_info a
WHERE
stock_status=1

	AND type = #{type}

AND NOT EXISTS (SELECT id FROM stock_growth b WHERE b.code=a.code

	AND
	b.year = #{year}


	AND
	b.quarter = #{quarter}

)
order by a.code
